export function createActivityTimeline(){const items=new Map(),announcements=[];let visible=true,followMode='auto';return Object.freeze({upsert(value){const item=normalizeActivity(value);items.set(item.id,Object.freeze({...items.get(item.id),...item}));if(visible)announcements.push(item.summary);return item},setVisible(v){visible=Boolean(v)},setFollowMode(v){if(!['auto','manual'].includes(v))throw new Error('invalid follow mode');followMode=v},flushAnnouncements(){return Object.freeze(announcements.splice(0))},snapshot({offset=0,limit=200}={}){const all=[...items.values()];return Object.freeze({activities:Object.freeze(all.slice(offset,offset+limit)),total:all.length,suspended:!visible,followMode,virtualized:all.length>limit})}})}
